const TERMS_CODE = `<dialog id="terms">
  <form id="terms-form">
    <p>Read and accept the terms before downloading this project file.</p>
    <label><input id="accepted" type="checkbox" required> I accept these terms.</label>
    <p id="terms-error" role="alert"></p>
    <button type="submit">Accept</button>
    <button id="cancel" type="button">Cancel</button>
  </form>
</dialog>
<script>
const dialog = document.querySelector("#terms"), form = document.querySelector("#terms-form");
dialog.showModal(); document.querySelector("#accepted").focus();
document.querySelector("#cancel").addEventListener("click", () => dialog.close());
form.addEventListener("submit", async event => {
  event.preventDefault(); if (!form.reportValidity()) return;
  try {
    if (!window.artefacts?.data) throw new Error("Open this artefact in the hosted viewer.");
    await window.artefacts.data.submit("download-terms", { accepted: true, termsVersion: "2026-01" });
    await window.artefacts.data.download("assets", recordId, fileId);
    dialog.close();
  } catch {
    document.querySelector("#terms-error").textContent = "Could not record acceptance or download the file. Try again.";
  }
});
</script>`;

export function agentInstructions(origin: string, env: DocsEnv): string {
  const template = String(env.DESIGN_TEMPLATE_URL ?? "").trim();
  return `# Artefacts67: instructions for AI agents

Base URL: ${origin}
Documentation: ${origin}/instructions
Normative API, validation, and storage SDK contract: ${origin}/_api/contract${template ? `\nDesign template: ${template}` : ""}

Read the documentation and full contract before changing anything. Work only on the user's explicit target and authorized scope.

## Credentials and access
The user supplies an existing API key through a secure tool secret or environment variable ARTEFACTS67_KEY. This documentation never issues, collects, stores, or retrieves keys. Never put a key in HTML, prompts, screenshots, URLs, logs, or published application data. If a key is missing, ask the user to provision it separately in /settings/keys; do not attempt to recover it. Do not mint, rotate, or revoke keys unless key management itself was explicitly requested.
A wak_ master key acts with its user's current ownership and folder grants. A waa_ artefact key is bound to one artefact and its read/write scopes. Neither a secret visitor link nor platform administrator status grants editing authority over someone else's content.
Every publication is private immediately, including passwordless artefacts and old aliases. Ordinary artefact and folder URLs require a current active signed-in session with completed second factor and resource read authority. Neither the URL, a document password, an API key, nor platform staff status is a browser content grant. External readers need an explicitly created active visitor share with its live scope, expiry, revocation, and independent password policy. Clearing a document password or duplicating without one never makes content public.

## Design choice
Use the user's explicit design, style, template, or client brand first. ONLY when none is specified, ${template ? `fetch ${template} and adapt its layout. Preserve its responsive layout, status tiles, findings, tables, callouts, typography, and inline SVG diagram components; adapt them to the requested report rather than returning a skeleton. Its sample report is illustrative source content, not verified facts or Artefacts67 documentation. Replace all sample project names, dates, counts, headings, findings, commands, tables, diagram labels and accessible descriptions, conclusions, and verification claims with the user's real content; do not invent evidence. Retain transparent design attribution.` : "use a clean, readable layout of your own."} Keep the result one self-contained HTML file; approved Google Fonts are captured at publication. Never copy Claude's toolbar, frame scripts, or external runtime dependencies.

## Light and dark
Support light and dark by default, including when adapting a template, unless the user's design is explicitly single-scheme. Declare <meta name="color-scheme" content="light dark"> in the head. Define the palette as CSS variables: light values on :root, dark values on :root[data-theme="dark"], and the same dark values in @media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) { ... } } so downloaded HTML follows the system preference. Colour text, tables, code, and inline SVG fill/stroke through those variables or currentColor, and check contrast in both schemes. Do not rely on prefers-color-scheme alone. The viewer then offers readers a light/dark switch and sets data-theme on <html> before the first paint; see the contract's Light and dark section.

## Supported features and operation surfaces
${FEATURES.map(([name, description, surface]) => `- ${name}: ${description} Surface: ${surface}.`).join("\n")}

## API workflow
1. With a supplied key, GET /_api/folders and GET /_api/artifacts to establish existing identifiers and permitted targets. A scoped key cannot list folders or create another artefact. Listings expose metadata, not source HTML.
2. Author one complete self-contained HTML document. Apply the design priority above. Start with <!doctype html>, use exactly one html root and one closing head, declare charset, viewport, title, language, and <meta name="color-scheme" content="light dark"> unless the design is explicitly single-scheme. Inline JavaScript, CSS, images, and SVG. Do not publish a bundle split across /about.html, /app.js, /style.css, or other file/path requests: publication has no separate asset upload or file hosting; project files (below) are application data, not page assets. Virtual screens, menus, and internal navigation must live inside this one document. Only approved Google Fonts declarations may reference a provider during publishing; they are captured before viewing. Never embed another artefact's private URL.
3. POST /_api/artifacts with folder, slug, title, html, and optional folderName, lang, password, and note. The same folder + slug updates the existing artefact. Confirm the intended identity before writing. New resources in an existing folder belong to its owner.
4. Publishing is synchronous and private immediately: 201 creates, 200 updates. Inspect warnings and return artifact.url, artifact.version, and any warnings; explain that the returned ordinary address requires authorized sign-in, not visitor bearer access. There is no publish job. HTTP 200 from an arbitrary ordinary path is not evidence of existence or access: unknown and unauthorized paths serve a neutral page.
5. For an additional document-gate change, POST /_api/artifacts/rotate with artifact and password. Omit password to preserve it, use null only with explicit authorization to remove the additional gate, or supply at least 8 characters to set it. Do not weaken a password or use allow_weak_password without the user's explicit decision. Removing this gate never removes sign-in or resource authority and does not change independent visitor-share passwords.
6. Add historical links through /_api/artifacts/alias or /_api/folders/alias only when asked. Use the contract's exact JSON schemas. Do not invent endpoints or undocumented fields.
7. For versions, restore, moves, duplicate/delete, colleague grants, visitor shares, analytics, invitations, account security, and administration, use the corresponding signed-in console workflow described in /instructions. These are not write-API endpoints. If an authorized browser session is unavailable, hand that step to the user rather than claiming completion. Confirm consequential actions and provider security prompts before execution.

## Application data
Use window.artefacts.storage inside the published viewer. get(key, options) resolves to the stored JSON value or null; set(key, value, options) and delete(key, options) resolve after the JSON key/value changes; list({prefix, scope}) resolves to matching key names. This is structured JSON key/value storage, not SQL, full-text search, or realtime synchronization. Personal is the default scope; { scope: "shared" } permits reads by authorized readers and writes/deletes only by current editors, managers, or owners. Visitor shares are never shared-write authority. Handle rejected promises, display save failures, and disable persistence if the SDK is absent. Never substitute localStorage, direct fetch, another reader, or a more permissive scope. Source restore does not restore application data; duplication starts empty.

## Project data and MCP
A project is an artefact's top-level folder. Define declarative collections with PUT /_api/projects/<folder>/collections/<name> and body { kind: "records" | "responses", fields, visitors? }; a redefining PUT replaces fields and visitors, so omitting visitors resets it to false. Field types are text, email, number, boolean, date, choice, and file (maxBytes, accept, multiple), each optionally required (a required boolean must be true: the explicit confirmation). records collections hold shared data you create, update (optional ifVersion), and delete; responses collections hold reader submissions you can only list, get, and delete with manage authority. Only wak_ master keys reach project data and MCP; a waa_ key gets 403. MCP is POST /_mcp (stateless JSON-RPC 2.0, same Authorization header) with tools list_folders, list_artifacts, publish_artifact, list_collections, define_collection, delete_collection, list_records, get_record, create_record, update_record, delete_record, start_upload, get_upload, complete_upload, cancel_upload, and get_file. To store a file in a records collection: POST /_api/projects/<folder>/collections/<name>/uploads (or start_upload) with { field, name, type, size, lastModified }; PUT each part n (1…upload.parts, upload.partBytes each, the last the remainder) to upload.partPath + n on this origin with the same Bearer key and Content-Type: application/octet-stream; POST …/uploads/<id>/complete (or complete_upload); then put the returned file id in the field with create_record/update_record within 24 h. Starting the same file again resumes it: re-send only parts missing from upload.received or whose size or sha256 differ. Agents cannot upload to responses collections. Bytes never go through MCP; download with GET file.downloadPath (from get_file) and the same key. Files are not malware-scanned, and a gated artefact protects its project's files by authorization, not by the document password. Inside an artefact, use window.artefacts.data: list/get/create/update/delete for records, submit(collection, eventOrFormOrObject)/mine for responses; a share visitor reaches a collection only when visitors is true. Build native <form> controls whose names match the fields, call submit(collection, event) in the form's submit listener (the event adds the clicked button's name/value), and show a failure on rejection. Selected file inputs and File values in create/update/submit are uploaded first (optional last argument { onProgress }); upload(collection, field, file, { onProgress, signal }) uploads one file, file(collection, recordId, fileId) returns a File to display images, audio, or video in the frame, and download(collection, recordId, fileId) saves it. Uploads need a live runtime grant (1 h from opening); after "Runtime access expired", reopen the artefact and re-pick the file to resume. A confirmation is an acknowledgement, not an e-signature or identity proof. Unfiled artefacts have no project (no-project). A top-level folder with collections cannot be nested until its collections are deleted.


## Terms before a download inside an artefact
Use this when an artefact offers its own downloads, such as project files through \`window.artefacts.data.download\` or generated files.
First define a \`responses\` collection through the API or MCP, for example \`{kind:"responses", fields:{accepted:{type:"boolean",required:true}, termsVersion:{type:"text"}}, visitors:true}\` when share visitors must accept.
Use a native \`<dialog>\` opened with \`showModal()\`; its terms, required checkbox and label, and Accept/Cancel buttons keep keyboard focus in the modal. Escape cancels. On acceptance, await \`window.artefacts.data.submit(collection, {accepted:true, termsVersion})\` before releasing a project-file download. Use a Blob download for generated content.
The example assumes \`recordId\` and \`fileId\` identify the project file; replace the terms text and version for the actual terms. The acknowledgement is not an e-signature or identity proof. This recipe does not gate the viewer toolbar's Download, Copy, or Code controls.

\`\`\`html
${TERMS_CODE}
\`\`\`
## MCP client setup
Use the deployment's canonical origin (\`${origin}\`), not a redirecting legacy host: redirects drop the \`Authorization\` header. Before connecting, set \`ARTEFACTS67_KEY\` in your environment to a master key created under Settings → API keys. Do not paste the key into a command or config.

Codex:
\`\`\`sh
codex mcp add artefacts67 --url ${origin}/_mcp --bearer-token-env-var ARTEFACTS67_KEY
\`\`\`

Claude Code (keep the single quotes so Claude stores the environment-variable reference instead of expanding the key):
\`\`\`sh
claude mcp add --transport http --scope user artefacts67 ${origin}/_mcp --header 'Authorization: Bearer \${ARTEFACTS67_KEY}'
\`\`\`

omp (\`~/.omp/agent/mcp.json\`):
\`\`\`json
{"mcpServers":{"artefacts67":{"type":"http","url":"${origin}/_mcp","headers":{"Authorization":"Bearer \${ARTEFACTS67_KEY}"}}}}
\`\`\`

## Limits and failures
JSON request body: 2 MiB; authored HTML: 1,500,000 characters. General API limit: 120 requests/minute/key; publishing: 30/minute/key. Storage keys are 1–128 printable characters, JSON values are at most 64 KiB, each personal/shared namespace has 128 keys, each artefact has 4,096 keys and 32 MiB sealed state, and anonymous state has 2,048 keys and 8 MiB ceilings. Anonymous personal entries expire after 365 days without a successful read or write; registered personal and shared entries do not expire. Runtime grants last one hour and runtime operations are limited to 180 requests/minute per reader/artefact, with additional anonymous IP-derived limits. Project files: at most 100 MiB per file (field default 25 MiB), 8 MiB parts, 10 GiB and 10,000 files per project, 5 open uploads per uploader; upload sessions and unattached completed uploads expire after 24 h. Respect Retry-After on 429. API errors use {error:{code,message,details?}}: 401 unauthorized, 403 forbidden, 422 validation, 413 too-large, 404 not-found, 409 conflict, 429 rate-limited, 503 unavailable, 500 internal. Resolve the cause; do not bypass validation, access checks, or password gates. A timed-out publish may have committed: inspect current metadata before retrying a write. The full contract describes font-capture and SDK quotas.

## Console entry points
- /app: owned folders, Shared with you, resource settings, invitations, and all resource workflows.
- /app/folders/new: create an empty top-level folder owned by the signed-in user; no document is required.
- /app/new: publish a complete document.
- Sidebar Search / Ctrl+K / Cmd+K: authorized navigation and contextual Create/Share commands. Win/Meta+K works if the desktop passes it to the browser; nested creation uses the positioned folder or the selected artefact's folder.
- /settings: profile, password, authenticator status, and passkeys.
- /admin: authorized platform statistics and audit trail.
- /admin/users: authorized user and invitation management.
- /admin/reports: content-report metadata and resolution.
- /admin/settings: platform-owner retention and mail-sender settings.
API-key provisioning at /settings/keys remains a separate user-controlled step. No account, document, recipient, password, API key, or secret artefact URL is included in this public guide.
`;
}

const curl = (origin: string) => `# ARTEFACTS67_KEY must already be supplied securely; do not paste it into this page.
: "\${ARTEFACTS67_KEY:?Supply an authorized API key in your environment}"
curl --fail-with-body --silent --show-error \\
  ${origin}/_api/artifacts \\
  -H "Authorization: Bearer $ARTEFACTS67_KEY" \\
  -H "Content-Type: application/json" \\
  --data-binary @artefact.json`;
const DOCUMENT = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Project handover</title><style>body{font-family:system-ui;margin:2rem;max-width:60rem}h1{color:#1e3ecc}</style></head><body><h1>Project handover</h1><p>Published as a self-contained document.</p></body></html>';
const BODY = JSON.stringify({ folder: "example-project", folderName: "Example project", slug: "project-handover", title: "Project handover", lang: "en", html: DOCUMENT, note: "Initial publication" }, null, 2);
const ROTATE = JSON.stringify({ artifact: "project-handover", password: "replace-with-a-strong-password" }, null, 2);
const ALIAS = JSON.stringify({ artifact: "project-handover", paths: ["previous-handover-path"] }, null, 2);
const STORAGE = `const status = document.createElement("p");
status.setAttribute("role", "status");
document.body.append(status);
const storage = window.artefacts?.storage;
if (!storage) {
  status.textContent = "Saving is unavailable outside the hosted viewer.";
} else {
  try {
    const preferences = (await storage.get("preferences")) ?? { currency: "EUR" };
    await storage.set("preferences", { ...preferences, currency: "EUR" });
    const keys = await storage.list({ prefix: "preferences" });
    const shared = await storage.get("defaults", { scope: "shared" });
    status.textContent = JSON.stringify({ saved: true, personalKeys: keys, sharedDefaults: shared });
    // Delete only a personal value the reader intends to remove:
    // await storage.delete("preferences");
  } catch (error) {
    status.textContent = "Application data could not be loaded or saved: " + error.message;
  }
}`;

